using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Gazette.Domain;
public sealed class GazettePublication:ITenantEntity{private GazettePublication(){} public GazettePublication(Guid municipalityId,Guid editionId,DateTimeOffset publishedAt,string sha256,string verificationCode,string publicUrl){Id=Guid.NewGuid();MunicipalityId=municipalityId;GazetteEditionId=editionId;PublishedAt=publishedAt;Sha256=sha256.Trim().ToLowerInvariant();VerificationCode=verificationCode.Trim();PublicUrl=publicUrl.Trim();}public Guid Id{get;private set;}public Guid MunicipalityId{get;private set;}public Guid GazetteEditionId{get;private set;}public DateTimeOffset PublishedAt{get;private set;}public string Sha256{get;private set;}=string.Empty;public string VerificationCode{get;private set;}=string.Empty;public string PublicUrl{get;private set;}=string.Empty;}
